#### 模式A: 表驱动状态机
```c
// 状态表结构
typedef struct {
    uint8_t currentState;
    uint8_t event;
    uint8_t nextState;
    void (*action)(void);
} StateTransition;
// 状态表定义
const StateTransition stateTable[] = {
    {STATE_IDLE,   EVENT_START,  STATE_RUNNING, action_start},
    {STATE_RUNNING, EVENT_STOP,   STATE_IDLE,    action_stop},
    {STATE_RUNNING, EVENT_PAUSE,  STATE_PAUSED,  action_pause},
    // ...
};
// 状态机执行
void processEvent(uint8_t event) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (stateTable[i].currentState == currentState &&
            stateTable[i].event == event) {
            currentState = stateTable[i].nextState;
            if (stateTable[i].action) stateTable[i].action();
            return;
        }
    }
}
```
#### 模式B: 函数指针状态机
```c
typedef void (*StateFunc)(void);
StateFunc currentState = state_idle;
void state_idle(void) {
    if (startCondition) {
        currentState = state_running;
    }
}
void state_running(void) {
    if (stopCondition) {
        currentState = state_idle;
    }
}
// 主循环
while (1) {
    currentState();
}
```
#### 模式选择矩阵
| 模式 | 状态数 | 可读性 | 可维护性 | 内存效率 | 适用场景 |
|------|--------|--------|----------|----------|----------|
| 表驱动 | >5 | 高 | 高 | 中 | 复杂系统、需要文档化 |
| 函数指针 | <5 | 中 | 中 | 高 | 简单系统、快速开发 |
| Switch-Case | <10 | 低 | 低 | 最高 | 初学者、原型验证 |

#### 三条铁律
1. **ISR最小化原则**
   - ISR只做最必要的事
   - 复杂处理交给主循环
   - ISR执行时间 < 禁用中断的最大容忍时间
2. **数据共享安全原则**
   - 共享数据必须保护
   - 主循环访问时禁用中断或使用原子操作
   - 避免ISR中调用非重入函数
3. **优先级分层原则**
   - 高优先级ISR处理紧急事件
   - 低优先级ISR处理常规事件
   - 遅优先级翻转
#### 安全数据共享实现
```c
// 方法1: 禁用中断
volatile uint32_t sharedData;
void updateSharedData(uint32_t newValue) {
    uint32_t intStatus = disableInterrupts();
    sharedData = newValue;
    restoreInterrupts(intStatus);
}
// 方法2: 双缓冲
volatile uint8_t bufferA[BUF_SIZE], bufferB[BUF_SIZE];
volatile uint8_t activeBuffer = 0; // ISR写入A，主循环读取B
// 方法3: 环形队列（原子索引）
volatile uint16_t head, tail; // 单字节操作天然原子
uint8_t queue[QUEUE_SIZE];
bool enqueue(uint8_t data) {
    uint16_t next = (head + 1) % QUEUE_SIZE;
    if (next == tail) return false; // 满
    queue[head] = data;
    head = next;
    return true;
}
```

#### 模式对比
| 模式 | 优点 | 缺点 | 适用场景 |
|------|------|------|----------|
| 完全静态 | 无碎片、可预测 | 灵活性差 | 安全关键系统 |
| 内存池 | 无碎片、部分灵活 | 需预估大小 | 固定类型分配 |
| 动态堆 | 高灵活 | 碎片风险 | 非关键系统 |
#### 内存池实现模板
```c
#define POOL_SIZE 64
#define BLOCK_SIZE 32
typedef struct {
    uint8_t data[BLOCK_SIZE];
    uint8_t inUse;
} MemoryBlock;
MemoryBlock pool[POOL_SIZE];
uint16_t freeCount = POOL_SIZE;
void* poolAlloc(void) {
    for (int i = 0; i < POOL_SIZE; i++) {
        if (!pool[i].inUse) {
            pool[i].inUse = 1;
            freeCount--;
            return pool[i].data;
        }
    }
    return NULL; // 池耗尽
}
void poolFree(void* ptr) {
    for (int i = 0; i < POOL_SIZE; i++) {
        if (pool[i].data == ptr) {
            pool[i].inUse = 0;
            freeCount++;
            return;
        }
    }
}
```

#### ✅ 正确案例: 时间触发调度器
```c
// 定义
#define MAX_TASKS 10
typedef struct {
    void (*task)(void);
    uint16_t period;
    uint16_t delay;
    uint8_t ready;
} Task;
Task taskList[MAX_TASKS];
uint16_t tickCount = 0;
// 调度器初始化
void schedulerInit(void) {
    for (int i = 0; i < MAX_TASKS; i++) {
        taskList[i].delay = taskList[i].period;
        taskList[i].ready = 0;
    }
}
// 定时器ISR（1ms tick）
void timerISR(void) {
    tickCount++;
    for (int i = 0; i < MAX_TASKS; i++) {
        if (--taskList[i].delay == 0) {
            taskList[i].ready = 1;
            taskList[i].delay = taskList[i].period;
        }
    }
}
// 主循环执行
void schedulerRun(void) {
    for (int i = 0; i < MAX_TASKS; i++) {
        if (taskList[i].ready) {
            taskList[i].task();
            taskList[i].ready = 0;
        }
    }
}
```
**优点**: 
- 时序完全确定
- 易于测试和验证
- 符合安全标准要求
#### ❌ 错误案例: 无约束的后台循环
```c
// 问题代码
while (1) {
    processADC();      // 时间不确定
    checkButtons();    // 可能阻塞等待
    updateDisplay();   // 时间可能很长
    sendData();        // 依赖外部响应
}
```
**问题**: 
- 执行时序不可预测
- 难以测试所有路径
- 不符合实时要求
- 可能遗漏关键任务

#### ✅ 正确案例: 表驱动的设备控制
```c
// 洗衣机控制器状态表
const StateTransition washerTable[] = {
    {IDLE,       BTN_START,   FILLING,     startFill},
    {FILLING,    LEVEL_OK,    WASHING,     startWash},
    {WASHING,    TIME_DONE,   RINSING,     startRinse},
    {RINSING,    TIME_DONE,   SPINNING,    startSpin},
    {SPINNING,   TIME_DONE,   IDLE,        finishCycle},
    {SPINNING,   DOOR_OPEN,   ERROR,       handleError},
    {ERROR,      BTN_RESET,   IDLE,        resetSystem},
};
// 可视化的状态转换图可从表格自动生成
// 便于文档化、测试、认证
```
**优点**: 
- 状态转换逻辑清晰可见
- 易于添加新状态和转换
- 可自动生成文档和测试
#### ❌ 错误案例: 散乱的条件判断
```c
// 问题代码
void controlWasher(void) {
    if (state == IDLE && buttonPressed) {
        state = FILLING;
        startFill();
    } else if (state == FILLING && waterLevelOK) {
        // 但没有处理doorOpen事件！
        state = WASHING;
        startWash();
    } else if (state == WASHING) {
        if (timeDone) {
            state = RINSING;
        } else if (motorError) {
            state = ERROR;
        }
        // 转换逻辑散落在多个函数中...
    }
    // ...难以追踪所有可能的路径
}
```
**问题**: 
- 转换逻辑分散难追踪
- 容易遗漏状态转换
- 测试覆盖率难以保证
- 添加新功能破坏原有逻辑

#### ✅ 正确案例: 中断标记+主循环处理
```c
// ISR只设置标志
volatile uint8_t adcReady = 0;
volatile uint16_t adcValue;
void adcISR(void) {
    adcValue = ADC_RESULT;
    adcReady = 1;  // 单字节原子操作
}
// 主循环处理
void mainLoop(void) {
    if (adcReady) {
        adcReady = 0;
        processADCData(adcValue);  // 复杂处理在主循环
    }
}
```
**优点**: 
- ISR极短（<10指令）
- 复杂处理可打断
- 系统响应时间可控
#### ❌ 错误案例: ISR中复杂处理
```c
// 问题代码
void adcISR(void) {
    uint16_t value = ADC_RESULT;
    // 在ISR中做复杂计算（危险！）
    float voltage = value * 3.3 / 4095;
    float temperature = (voltage - 0.5) * 100;
    // 在ISR中发送数据（可能阻塞！）
    uartSendString("Temp: ");
    uartSendNumber(temperature);
    // 在ISR中更新显示（时间很长！）
    updateLCD(temperature);
}
```
**问题**: 
- ISR执行时间过长
- 其他中断被阻塞
- 可能导致系统崩溃
- 非重入函数风险
